<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    background: #eceded;
    font-family: -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
    color: #1d1d1f;
  }
  .navbar {
    display: flex;
    align-items: center;
    padding: 26px 40px;
    font-size: 15px;
    color: #6e6e73;
  }
  .navbar a {
    color: #6e6e73;
    text-decoration: none;
    margin-right: 32px;
  }
  .navbar a.active {
    color: #1d1d1f;
    font-weight: 600;
    text-decoration: underline;
  }
  .navbar .spacer { flex: 1; }
  .navbar .pageinfo {
    color: #1d1d1f;
    white-space: nowrap;
  }
  .content {
    padding: 40px 40px 60px 40px;
  }
  h1.title {
    font-size: 64px;
    font-weight: 800;
    color: #1d1d1f;
    margin: 40px 0 40px 0;
  }
  .grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr 1fr 1fr;
    grid-template-rows: auto auto;
    gap: 16px;
  }
  .card {
    background: #ffffff;
    border-radius: 18px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }
  .card-pad {
    padding: 32px 28px;
  }
  .card h2 {
    font-size: 24px;
    font-weight: 700;
    margin: 0 0 14px 0;
    line-height: 1.25;
  }
  .card p {
    font-size: 15px;
    line-height: 1.5;
    color: #3a3a3c;
    margin: 0 0 16px 0;
  }
  .readmore {
    font-size: 15px;
    font-weight: 700;
    color: #1d1d1f;
    margin-top: auto;
  }
  .readmore a {
    color: #2f7a4d;
    text-decoration: underline;
    font-weight: 700;
  }

  /* Card 1: full height, text top, image bottom flush */
  .card1 {
    grid-column: 1;
    grid-row: 1 / 3;
    justify-content: flex-start;
  }
  .card1 .placeholder {
    flex: 1;
    margin: 0;
    border-radius: 0;
    min-height: 260px;
  }

  /* Card 2: text + watch image side by side */
  .card2 {
    grid-column: 2 / 4;
